"""Freeze Unicode categories from the same pinned Rust regex as tokenizer.json."""
from pathlib import Path
import argparse,hashlib,json

def main():
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--output',type=Path,required=True);p.add_argument('--report',type=Path,required=True);a=p.parse_args()
 import tokenizers
 from tokenizers import Regex,pre_tokenizers
 assert tokenizers.__version__=='0.22.2','Requalify category generation when the reference engine changes'
 universe=''.join(chr(cp) for cp in range(0x110000) if not 0xD800<=cp<=0xDFFF);tables={}
 for name,category in (('Letters',r'\p{L}'),('Marks',r'\p{M}'),('Numbers',r'\p{N}'),('Spaces',r'\s')):
  splitter=pre_tokenizers.Split(Regex('[^'+category+']+'),behavior='removed');pieces=splitter.pre_tokenize_str(universe);ranges=[]
  for piece,_ in pieces:
   first,last=ord(piece[0]),ord(piece[-1]);assert last-first+1==len(piece);assert not ranges or ranges[-1][1]<first;ranges.append((first,last))
  tables[name]=ranges
 lines=['// SPDX-FileCopyrightText: 2024-2026 CantorAI Inc.','// SPDX-License-Identifier: Apache-2.0','// Generated by generate_qwen_unicode_categories.py using tokenizers0.22.2.','// Categories come from its actual Rust Unicode regex; no locale/runtime dependency.','#pragma once','#include <cstddef>','#include <cstdint>','namespace Garnet::Tokenization::Unicode {','struct Range { std::uint32_t first, last; };']
 for name,ranges in tables.items():
  lines.append('inline constexpr Range k'+name+'[] = {');lines.extend('    {0x%Xu, 0x%Xu},'%pair for pair in ranges);lines.append('};')
 lines.extend(['template<std::size_t N> inline bool Contains(std::uint32_t cp, const Range (&ranges)[N]) {','    std::size_t lo=0, hi=N;','    while (lo<hi) {','        const std::size_t mid=lo+(hi-lo)/2;','        if (cp<ranges[mid].first) hi=mid;','        else if (cp>ranges[mid].last) lo=mid+1;','        else return true;','    }','    return false;','}','} // namespace Garnet::Tokenization::Unicode',''])
 raw='\n'.join(lines).encode();assert not a.output.exists() or a.output.read_bytes()==raw
 if not a.output.exists():a.output.write_bytes(raw)
 report={'status':'unicode_category_tables_generated_from_pinned_rust_regex','tokenizers_version':tokenizers.__version__,'unicode_scalar_values_classified':len(universe),'ranges':{n:len(v) for n,v in tables.items()},'header_sha256':hashlib.sha256(raw).hexdigest(),'scope':'Deterministic CPU Unicode class membership only; native full tokenizer parity still requires differential corpus/edge tests.'};a.report.write_text(json.dumps(report,indent=2),encoding='utf8');print(json.dumps(report))
if __name__=='__main__':raise SystemExit(main())
